selected.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(2, 4):
    for group in combinations(ids, k):
        candidate = list(group)
        if valid(candidate):
            result = candidate
            break
    if result:
        break
ordered = []
for x in sorted(options, key=lambda x: (x['rank'], x['id'])):
    if x['id'] in result:
        ordered = ordered + [x['id']]
result = ordered

selected.effects:
artifact = read('/output/selection')
if artifact:
    result = artifact
if artifact and valid(result):
    if status('report') == 'not_sent':
        send('report', 'team', result)
    elif status('report') == 'sent':
        pass
    else:
        status('report')
else:
    if not artifact and valid(result):
        write('/output/selection', result)
        if status('report') == 'not_sent':
            send('report', 'team', result)
        else:
            status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')
